# Jana suara Bahasa Melayu (Microsoft Yasmin) untuk video LO to Screen.
# Keperluan: Python 3 (python.org). Jalankan: jana_suara.bat  (atau: python jana_suara.py)
import asyncio, edge_tts
VOICE = "ms-MY-YasminNeural"   # suara lelaki: "ms-MY-OsmanNeural"
RATE = "+0%"                  # laju sedikit: "+8%"
N = ['LO to Screen ialah satu proses yang membantu pendidik membina video pengajaran secara lebih terancang, bermula dengan objektif pembelajaran dan bukannya terus menghasilkan prompt AI.', 'Perjalanan ini bermula dengan Learning Outcome atau LO. Kita perlu jelas terlebih dahulu, selepas menonton video ini, apakah perkara yang pelajar sepatutnya tahu, faham atau boleh lakukan.', 'Selepas LO ditentukan, kita memilih Visual Evidence. Maksudnya, apakah visual yang paling jelas boleh membantu pelajar melihat dan memahami konsep tersebut. Kita tidak memilih visual sekadar untuk mencantikkan video, tetapi visual yang benar-benar menyokong pembelajaran.', 'Seterusnya, kita menentukan strategi pengajaran yang sesuai. Adakah kita mahu menerangkan konsep, membandingkan dua keadaan, menunjukkan sesuatu proses atau menyelesaikan satu masalah?', 'Daripada strategi tersebut, kita mula membina Scene Map. Kandungan dipecahkan kepada beberapa scene pendek supaya setiap scene mempunyai satu fokus yang jelas. Untuk video berasaskan Google Flow, satu scene biasanya dirancang sekitar lapan saat.', 'Dalam proses ini, AI bukan sekadar digunakan untuk menghasilkan video. Kita menggunakan AI Checkpoints untuk berbincang, menyemak dan memperhalusi keputusan pengajaran sebelum bergerak ke langkah seterusnya.', 'Selepas Scene Map siap, kita memastikan continuity antara setiap scene. Watak, persekitaran, arah visual dan gaya persembahan perlu konsisten supaya video terasa seperti satu perjalanan pembelajaran yang lengkap, bukannya beberapa klip yang terpisah.', 'Barulah kita masuk ke peringkat Google Flow, di mana setiap scene dijana satu demi satu berdasarkan perancangan yang telah dibuat.', 'Klip yang siap kemudian dibawa ke proses editing, contohnya menggunakan CapCut. Di sinilah kita boleh menambah voice over, caption, overlay, animasi atau elemen sokongan yang membantu pelajar memberi perhatian kepada perkara penting.', 'Akhirnya, kita memperoleh sebuah video PdP yang siap digunakan.', 'Jadi, LO to Screen sebenarnya bukan sekadar proses menghasilkan video menggunakan AI. Ia ialah satu cara berfikir.', 'Bermula dengan apa yang pelajar perlu belajar, menentukan bagaimana mereka perlu melihatnya, kemudian barulah memilih bagaimana AI boleh membantu kita menghasilkan pengalaman pembelajaran tersebut.', 'Daripada Idea, kepada Plan, Create, Teach dan akhirnya Impact.', 'Video mungkin pendek, tetapi apabila perancangannya tepat, impaknya kepada pembelajaran boleh menjadi jauh lebih besar.', 'Video kecil, impak besar.']
async def main():
    for i, text in enumerate(N):
        out = f"{i:02d}.mp3"
        await edge_tts.Communicate(text, VOICE, rate=RATE).save(out)
        print("siap", out)
asyncio.run(main())
